# Helper to create an IPv6 header
# Note: This is a simplified IPv6 header for demonstration purposes.
# In a real scenario, the OS handles the IP header when using standard sockets.
# Here we use a raw socket to demonstrate the packet structure and eavesdropping.

def create_ipv6_packet(src, dst, payload):
    """
    Creates a raw IPv6 packet with the given payload.
    This is primarily for educational purposes to show the packet structure.
    """
    # IPv6 Header fields:
    # Version (4 bits), Traffic Class (8 bits), Flow Label (20 bits)
    # Payload Length (16 bits), Next Header (8 bits), Hop Limit (8 bits)
    # Source Address (128 bits), Destination Address (128 bits)
    
    version = 6
    traffic_class = 0
    flow_label = 0
    payload_length = len(payload)
    next_header = 59  # No Next Header (used for raw socket testing)
    hop_limit = 64
    
    # Pack the first 40 bytes of the IPv6 header
    ipv6_header = struct.pack('!BBHHHBB', 
                              (version << 4) | (traffic_class >> 4), 
                              ((traffic_class & 0xF) << 4) | ((flow_label >> 16) & 0xF),
                              (flow_label & 0xFFFF),
                              payload_length,
                              next_header,
                              hop_limit
                             )
    
    # Note: The above packing is simplified and might not be fully correct for all fields.
    # For a real raw socket send, we'd need to properly pack the 40-byte header.
    # However, for eavesdropping demonstration, we can use a standard socket and capture.
    return ipv6_header + payload

def eavesdropper(interface='lo'):
    """
    Simulates an on-path attacker capturing IPv6 packets.
    Uses a raw socket to listen for IPv6 traffic.
    """
    # Create a raw socket for IPv6
    sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_IPV6)
    
    # Bind to the loopback interface for local testing
    # In a real scenario, this would be the network interface of the attacker
    sock.bind(('::1', 0))
    
    print("[Eavesdropper] Listening for IPv6 packets on loopback...")
    
    try:
        while True:
            # Receive a packet
            packet, addr = sock.recvfrom(65535)
            
            # Parse the IPv6 header (first 40 bytes)
            if len(packet) >= 40:
                # Extract source and destination addresses
                src_addr = socket.inet_ntop(socket.AF_INET6, packet[8:24])
                dst_addr = socket.inet_ntop(socket.AF_INET6, packet[24:40])
                
                # Extract payload (everything after the 40-byte header)
                payload = packet[40:]
                
                print(f"[Eavesdropper] Captured packet from {src_addr} to {dst_addr}")
                print(f"[Eavesdropper] Payload (plaintext): {payload.decode('utf-8', errors='ignore')}")
                print("[Eavesdropper] ---")
                
                # Break after capturing one packet for demonstration
                break
    except KeyboardInterrupt:
        print("[Eavesdropper] Stopped.")
    finally:
        sock.close()

def sender():
    """
    Sends an unencrypted IPv6 packet.
    """
    # Create a standard UDP socket for simplicity
    # In a real scenario, this could be any unencrypted protocol
    sock = socket.socket(socket.AF_INET6, socket.SOCK_DGRAM)
    
    # Destination: loopback IPv6 address
    dst_addr = '::1'
    dst_port = 12345
    
    # Payload: sensitive information
    payload = b"Sensitive Data: User credentials and personal information."
    
    print(f"[Sender] Sending unencrypted IPv6 packet to {dst_addr}:{dst_port}")
    print(f"[Sender] Payload: {payload.decode('utf-8')}")
    
    # Send the packet
    sock.sendto(payload, (dst_addr, dst_port))
    
    # Close the socket
    sock.close()
    print("[Sender] Packet sent.")

